<section class="container section narrow"><h1><?= !empty($isCreate) ? 'Create cookbook' : 'Edit cookbook' ?></h1><form action="<?= e($formAction) ?>" method="post" class="stack-form card" data-cookbook-form><?= \App\Util\Csrf::field() ?><label>Title <input type="text" name="title" value="<?= e($cookbook['title'] ?? '') ?>" required></label><label>Description <textarea name="description" rows="3"><?= e($cookbook['description'] ?? '') ?></textarea></label><div id="cookbook-sections"><?php foreach (($cookbook['sections'] ?? [['title' => '', 'recipes' => [['recipe_id' => '', 'scale' => 1, 'notes' => '']]]]) as $sectionIndex => $section): ?><div class="card nested-card cookbook-section-editor" data-cookbook-section><label>Section title <input type="text" name="sections[<?= $sectionIndex ?>][title]" value="<?= e($section['title'] ?? '') ?>"></label><div class="stack-form"><?php $recipeEntries = $section['recipes'] ?? [['recipe_id' => '', 'scale' => 1, 'notes' => '']]; ?><?php foreach ($recipeEntries as $recipeIndex => $entry): ?><div class="cookbook-entry-row"><label>Recipe<select name="sections[<?= $sectionIndex ?>][recipes][<?= $recipeIndex ?>][recipe_id]"><option value="">Choose recipe</option><?php foreach ($recipes as $availableRecipe): ?><option value="<?= e($availableRecipe['id']) ?>" <?= ($entry['recipe_id'] ?? '') === $availableRecipe['id'] ? 'selected' : '' ?>><?= e($availableRecipe['title']) ?></option><?php endforeach; ?></select></label><label>Scale <input type="number" step="0.25" min="0.25" name="sections[<?= $sectionIndex ?>][recipes][<?= $recipeIndex ?>][scale]" value="<?= e((string) ($entry['scale'] ?? 1)) ?>"></label><label>Notes <input type="text" name="sections[<?= $sectionIndex ?>][recipes][<?= $recipeIndex ?>][notes]" value="<?= e($entry['notes'] ?? '') ?>"></label></div><?php endforeach; ?></div></div><?php endforeach; ?></div><button class="button" type="submit">Save cookbook</button></form></section>
